 "content": "def transform(grid):
    """Overlay copies of the marked shape wherever its full footprint is background."""
    h, w = len(grid), len(grid[0])
    marks = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 5]
    r0, c0 = min(r for r, c in marks), min(c for r, c in marks)
    shape = {(r-r0, c-c0) for r, c in marks}
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            pts = [(r+dr, c+dc) for dr, dc in shape]
            if all(0 <= rr < h and 0 <= cc < w and grid[rr][cc] in (0, 5) for rr, cc in pts):
                for rr, cc in pts:
                    if grid[rr][cc] == 0:
                        out[rr][cc] = 5
    return out
